D = []
def add(**k): D.append(k)

def yoga_fakta(orig, opening, belast, b3, rengor, cykel, uppgr, garanti, info, tail):
    return (f"{orig}. {opening} Oavsett om du ligger ner för magövningar eller utövar yoga sittande, ger en matta extra komfort och stabilitet. Med Tunturis extra tjocka 8 mm matta har du en yogamatta, sportmatta och träningsmatta i ett. Mattan ger extra komfort, {belast} och är tillverkad av miljövänligt material. "
     "Fördelar med Tunturi yogamatta - Träningsmatta - Sportmatta: Extra tjock 8 mm matta för maximal komfort under träning. Perfekt för yoga-, fitness- och pilatesklasser. "
     f"{b3} Halkfri, lätt att rengöra och biologiskt nedbrytbar. Levereras med praktisk bärväska och gratis app. "
     "Tjock yogamatta för extra komfort: Tunturi Yoga Mat 8 mm är idealisk för alla yogaformer där du utför många positioner liggande eller sittande, som yin yoga, yoga nidra och meditation. Detta beror på att mattan är tjockare än \"vanliga\" yogamattor (3-4 mm), vilket ger extra komfort och gör att du kan slappna av snabbare. Perfekt om ett hårt golv hemma eller på gymmet lätt orsakar obehag. "
     "Mindre belastning på muskler och leder: Mattan är också mycket lämplig för andra träningsformer som fitness och pilates, även om du lider av (kronisk) smärta eller återhämtar dig från en skada. Tjockleken minskar belastningen på rygg, ben, knän, vrister och leder. "
     f"Miljövänlig och lätt att rengöra: Yogamattan är tillverkad av 100 % TPE: en kombination av gummi och plast. Detta miljövänliga material är 100 % biologiskt nedbrytbart, extra mjukt, halkfritt och motståndskraftigt mot svett, lukt och bakterier. Så du behöver inte oroa dig för synliga svettfläckar. För extra hygien kan du enkelt rengöra mattan med lite {rengor}. "
     "Bärväska ingår: Träningsmattan finns i 7 trendiga färger och levereras med en bärväska så att du enkelt kan ta med den vart du än går. Detta kan vara särskilt praktiskt på gymmet, eftersom du aldrig behöver undra om mattan har rengjorts nyligen. "
     "Är det första gången du använder en matta? Ta ut den ur förpackningen, rulla ut den på golvet och låt den vila i några timmar. Detta förhindrar att mattan rullar ihop sig när du först lägger dig på den. "
     f"Om Tunturi: Må bättre varje dag. Det är Tunturis motto. Våra rötter finns i Finland, där två bröder grundade en {cykel} 1922. Nu, över 100 år senare, är vi ett holländskt företag och ett globalt varumärke. Vi stöder dig på din resa mot en frisk och vältränad kropp, ett balanserat sinne och ett lyckligt liv. Vi gör detta med ett brett utbud av konditions- och styrketräningsutrustning, tillbehör och stödsystem. Det är ett ständigt växande och {uppgr} sortiment av högkvalitativa produkter och {garanti}. "
     f"Mer information: Mått. Vikt: 950 gr Material: TPE {info} EAN: 8717842035375. {tail}")

YOGA_PASSAR = ["Yoga där du utför många positioner liggande eller sittande, till exempel yin yoga, yoga nidra och meditation","Fitness och pilates","Dig som vill ha en tjockare matta än vanliga yogamattor (3–4 mm)"]
YOGA_FAQ = [("Vad ska jag göra när mattan är ny?","Ta ut den ur förpackningen, rulla ut den på golvet och låt den vila i några timmar.")]
YOGA_BEK = ["Källan har en tom rad \"Mått.\". Mattans längd och bredd saknas.","Texten säger \"gratis app\" men inte vilken. Uppgiften är utelämnad.","Alla tre Tunturi Yogamat 8mm-produkter (ljusblå, Army Green, Petrol Blue) har samma EAN 8717842035375. Det stämmer knappast för tre färger.","Miljöpåståendena (\"miljövänligt\", \"100 % biologiskt nedbrytbart\") och hälsopåståendena (smärta, skada, leder) är utelämnade och kräver belägg om de ska användas.","Märkesbakgrund (rötter i Finland, 1922) är leverantörens standardtext och är utelämnad."]
YOGA_MOT = "Fakta ur källan. Utelämnat: hälsopåståenden (mindre belastning på leder, smärta, skada), miljöpåståenden (miljövänlig, biologiskt nedbrytbar), superlativ (maximal komfort, perfekt, idealisk), säljfraser, gratis app och Tunturis märkestext."

